// Cuántas búsquedas de un rubro se disparan POR TANDA.
//
// Esto es importante: DEFAULT_CATALOG_QUERIES tiene más de 1700 entradas, y
// antes se disparaban TODAS las de un rubro apenas tocabas el chip — 538
// pedidos de una sentada para "Almacén", por ejemplo. Eso significaba tres
// problemas a la vez: la app se auto-bloqueaba con su propio rate limit
// (429), le pegaba a la API pública de Precios Claros como un scraper, y el
// rubro tardaba una eternidad en terminar de cargar.
//
// Con 12 búsquedas x 8 resultados ya entran ~96 productos reales por tanda,
// que es más de lo que alguien scrollea de una. El resto del catálogo sigue
// disponible con el botón "Ver más productos" (carga la tanda siguiente) y
// como sugerencias del buscador (lib/relatedSearches.ts).
export const CATALOG_QUERIES_PER_PAGE = 12;

// Carnes se separó de Frescos: hasta ahora todo lo que era carne, pollo,
// pescado y achuras vivía dentro de "Frescos" mezclado con fiambres, quesos,
// pastas y fruta. Las búsquedas de arriba siguen escritas con category
// 'Frescos' (son más de 500 líneas); acá se reparten por lo que dice cada
// búsqueda: lo que es carne, ave, pescado o embutido fresco pasa a 'Carnes',
// y fiambres (jamón, salame, mortadela), quesos, huevos y pastas frescas se
// quedan en Frescos. Para mover una búsqueda de rubro basta con que su texto
// entre (o salga) de estas dos expresiones.
const NO_ES_CARNE = /queso|fiambre|jamon|salam|mortadela|salchichon|pate$|lengua a la|arrollado de|pastron|lomito ahumado|bondiola (cocida|ahumada)|paleta (cocida|ahumada)|leberwurst|sopressata|coppa|guanciale|speck|soja|berenjena|pasta|ravioles|sorrentinos|capeletis|lasagna|tallarines|fideos|nnoquis|ñoquis|tapas|masa|huevo|tofu|hummus|ensalada|salsa|pesto/;
const ES_CARNE = /pollo|pechuga|muslo|suprema|alita|ala de|higad|carcasa|carne|asado|vacio|matambre|entra[ñn]a|falda|roast beef|nalga|cuadril|colita|bife|peceto|osobuco|churrasco|carnaza|paleta de|costill|costeleta|carre|pechito|cerdo|milanesa|hamburguesa|albondiga|pincho|brochette|bondiol|chorizo|morcilla|longaniza|chistorra|salchicha|panceta|tocino|cordero|conejo|pato|pavo|molleja|chinchul|ri[ñn]on|hueso|lomo|entrecot|chulet|punta de espalda|palomita|tortuguita|aguja|brazuelo|solomillo|ribs|garr[oó]n|cuadrada|bola de lomo|lengua vacuna|corazon vacuno|sesos|rabo|achuras|tripa|mondongo|criadillas|pescado|merluza|salmon|filet de|camaron|calamar|langostino|rabas|mejillon|trucha|centolla|ostra|almeja|berberecho|sardina|pejerrey|abadejo|parrillada|manitas|oreja de cerdo|cuero de cerdo|chicharron|butifarra|sobrasada|t bone|porterhouse|chuleton|pollo/;

export const DEFAULT_CATALOG_QUERIES: { category: string; query: string }[] = RAW_CATALOG_QUERIES.map((q) =>
  q.category === 'Frescos' && !NO_ES_CARNE.test(q.query) && ES_CARNE.test(q.query) ? { ...q, category: 'Carnes' } : q
);

// Búsquedas "fijas" de la primera tanda de un rubro.
//
// Frescos tiene cientos de búsquedas (quesos, cortes, fiambres, pescados) y la
// rotación diaria de abajo hacía que abrir el rubro mostrara hoy una tanda
// de quesos, mañana una de cortes de cerdo… y que lo primero que uno espera
// encontrar (el asado, el salame, el chorizo) apareciera recién después de
// varios "Ver más". Estas son las que tienen que verse SIEMPRE al abrir el
// rubro; el resto sigue rotando por día desde la segunda tanda.
export const CATALOG_PINNED: Record<string, string[]> = {
  Carnes: [
    'asado',
    'tira de asado',
    'vacio',
    'matambre',
    'chorizo',
    'morcilla',
    'bondiola',
    'carne picada',
    'pollo',
    'milanesa',
    'pechuga de pollo',
    'nalga',
  ],
  Frescos: [
    'jamon cocido',
    'jamon crudo',
    'salame',
    'salamin',
    'mortadela',
    'queso fetita',
    'queso cuartirolo',
    'queso tybo',
    'queso mantecoso',
    'provoleta',
    'ravioles de ricota',
    'papa',
  ],
};

// Devuelve la tanda `page` (0-indexada) de búsquedas de un rubro.
//
// El punto de arranque rota por día para que la vidriera no muestre siempre
// exactamente los mismos 96 productos: hoy empieza en una parte de la lista,
// mañana en otra. Es determinístico dentro del mismo día, así que el caché
// del servidor (revalidate) sigue sirviendo y no se multiplica el trabajo.
//
// Si el rubro tiene búsquedas fijas (CATALOG_PINNED), la tanda 0 son esas y
// la rotación arranca desde la tanda 1, sobre el resto.
export function catalogQueriesFor(category: string, page = 0): { category: string; query: string }[] {
  const pinned = CATALOG_PINNED[category]?.slice(0, CATALOG_QUERIES_PER_PAGE);
  let all = DEFAULT_CATALOG_QUERIES.filter((q) => q.category === category);

  if (pinned?.length) {
    if (page === 0) return pinned.map((query) => ({ category, query }));
    const fijas = new Set(pinned);
    all = all.filter((q) => !fijas.has(q.query));
    page -= 1;
  }

  if (all.length <= CATALOG_QUERIES_PER_PAGE) return all;

  const dayIndex = Math.floor(Date.now() / 86_400_000);
  const start = ((dayIndex + page) * CATALOG_QUERIES_PER_PAGE) % all.length;

  const out: { category: string; query: string }[] = [];
  for (let i = 0; i < CATALOG_QUERIES_PER_PAGE; i++) {
    out.push(all[(start + i) % all.length]);
  }
  return out;
}

// Cuántas tandas tiene un rubro (para saber cuándo esconder "Ver más").
export function catalogPagesFor(category: string): number {
  const pinned = CATALOG_PINNED[category]?.slice(0, CATALOG_QUERIES_PER_PAGE);
  const fijas = new Set(pinned ?? []);
  const total = DEFAULT_CATALOG_QUERIES.filter((q) => q.category === category && !fijas.has(q.query)).length;
  return Math.max(1, Math.ceil(total / CATALOG_QUERIES_PER_PAGE) + (pinned?.length ? 1 : 0));
}


